# name: ra-weierstrassnowheredifferentiable-test
# technique: test a claim no recipe certifies, at instances Sage evaluates exactly or by intervals
# goal: sage_test KaluzaKlein.RealAnalysis.Continuity.WeierstrassNowhereDifferentiable file "ra-weierstrassnowheredifferentiable-test.sage"
# description: the difference quotients of W at x grow without bound as h = 13^(-m) → 0 (128-bit intervals, 60 terms, m = 1..4)
SEED = 0  # the instances are listed, no sampling
R = RealIntervalField(128)
def B(b):
    return QQ(1 if bool(b) else 0)
RI = RealIntervalField(256)
def O(values, lhs, rhs, rel='==', edge=False):
    # symbolic values (π, e, logs, limits Sage computed) are compared by 256-bit intervals; rationals exactly
    if any(hasattr(v, 'parent') and v.parent() is SR for v in (lhs, rhs)):
        lhs, rhs = RI(lhs), RI(rhs)
    return oracle_instance(*values, lhs=lhs, rhs=rhs, relation=rel, edge=edge)
def W(xv, terms=60):
    return sum(R(QQ(1) / 2) ** k * (R(13) ** k * R(pi) * R(xv)).cos() for k in range(terms))
instances = []
for xv, edge in [(0, True), (QQ(1) / 3, False), (QQ(1) / 7, False)]:
    qs = [abs((W(xv + QQ(1) / 13 ** m) - W(xv)) * 13 ** m) for m in range(1, 5)]
    instances.append(O([str(xv)], B(all(qs[i + 1] > qs[i] for i in range(3))), QQ(1), edge=edge))
